toolUseResult.originalFile:
.collection-categories {
  display: flex;
  gap: 4px;
  flex-wrap: nowrap;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding-inline: var(--page-margin, 1.5rem);
}

.collection-categories::-webkit-scrollbar {
  display: none;
}

.category-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  border-radius: 20px;
  padding: 8px 16px;
  font-family: var(--font-subheading--family);
  font-weight: 700;
  font-size: 1rem;
  line-height: 20px;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  border: 1px solid #D9D9DB;
  color: #414141;
  background-color: transparent;
  transition: background-color 0.2s ease, color 0.2s ease, border-color 0.2s ease;
}

.category-pill:hover {
  border-color: #414141;
}

.category-pill--active {
  background-color: #8C0132;
  border-color: #8C0132;
  color: #FFFFFF;
}

.category-pill--active:hover {
  border-color: #8C0132;
}

.category-pill__dot {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  flex-shrink: 0;
}

.category-pill__check {
  display: inline-flex;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

.category-pill__check svg {
  width: 100%;
  height: 100%;
}

/* Promo card styles */
.plp-promo-card {
  display: flex;
  flex-direction: column;
  position: relative;
  border-radius: 16px;
  overflow: hidden;
  height: 100%;
  min-height: 534px;
  text-decoration: none;
  color: #FFFFFF;
}

.plp-promo-card__media {
  position: absolute;
  inset: 0;
}

.plp-promo-card__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.plp-promo-card__overlay {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 24px 24px 16px 24px;
  border-radius: 0 0 8px 8px;
  background: rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
}

.plp-promo-card__heading {
  margin: 0;
  font-family: var(--font-subheading--family);
  font-weight: 700;
  font-size: 1.5rem;
  line-height: 28px;
  color: #FFFFFF;
}

.plp-promo-card__text {
  margin: 0;
  font-family: var(--font-heading--family);
  font-weight: 400;
  font-size: 1rem;
  line-height: 20px;
  letter-spacing: -0.5px;
  color: #FFFFFF;
}

.plp-promo-card__link {
  font-family: var(--font-subheading--family);
  font-weight: 500;
  font-size: 0.875rem;
  line-height: 16px;
  color: #FFFFFF;
  text-decoration: underline;
}

/* Product grid promo item */
.product-grid__item--promo {
  min-height: 534px;
}

@media screen and (max-width: 749px) {
  .plp-promo-card {
    min-height: 380px;
  }

  .product-grid__item--promo {
    min-height: 380px;
  }

  .plp-promo-card__heading {
    font-size: 1.25rem;
    line-height: 24px;
  }
}

